import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"圣保罗书院 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-ffb9bd6b","school_zh":"圣保罗书院","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"圣保罗书院 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-SPC-2021-SCHOLAR","C1821-SPC-2021"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-ffb9bd6b/s1/2020-21-interview.md","filePath":"reports/school-ffb9bd6b/s1/2020-21-interview.md"}'),p={name:"reports/school-ffb9bd6b/s1/2020-21-interview.md"};function a(n,o,c,l,g,d){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="圣保罗书院-·-2020-21年度-·-中一-·-面试" tabindex="-1">圣保罗书院 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#圣保罗书院-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;圣保罗书院 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-ffb9bd6b">← 返回圣保罗书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-spc-2021-scholar" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-spc-2021-scholar" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-spc-2021-scholar}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一奖学金甄选</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>奖学金会面</strong></p><p>一组由校长及副校长以交谈形式进行，中英文交替；另一组全程粤语。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>个人与学校认识</strong></p><p>自我介绍、介绍家庭成员，说明怎样认识圣保罗及对学校了解多少。</p></blockquote><blockquote><p><strong>语文：</strong> 中文；另有全粤语反馈</p><p><strong>训练、择校与奖学金</strong></p><p>每周打多少次乒乓球、比赛成绩、是否认识在校学生；另一组问路程远是否辛苦、取得好成绩有什么学习方法、没有奖学金是否仍会入读、是否把学校放在首选，最后可向学校提问。</p></blockquote><h2 id="record-c1821-spc-2021" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-spc-2021" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-spc-2021}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>准备与面谈时长</strong></p><p>有考生获1分钟准备后朗读并答题；另一组中文约6分钟、阅读后答两题，英语没有明确限时、约10分钟、阅读后答三题。</p></blockquote><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>成语故事与情境改写</strong></p><p>阅读“滥竽充数”，指出对应成语；解释南郭先生为何能蒙混过关，以及若可重新来过会怎样改变命运。考生举例可学好吹竽而不用离开乐团。</p><p><strong>孝亲故事与人物评价</strong></p><p>阅读“卧冰求鲤”后，在三个选项中选最合适标题，并评价王祥是怎样的人。故事涉及严冬为继母求鱼；其余两个标题选项未记下。</p><p><strong>文章赏析与个人选择</strong></p><p>辨认修辞，如顶真，说明主旨或内容排列方式；“落花生”一题比较文中的苹果与花生，并选择想成为哪一种。另请分享一次上台表演的经过感受，或除文中炮弹演习之外，什么经历令人震撼。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读主题与理解</strong></p><p>不同考生遇到月光在不同日期的变化、太空食物、宠物、频繁换手机引起环保问题、YouTube及网上学习等文章；需要回答文章内容，再作延伸表达。</p><p><strong>环保、动物与媒体观点</strong></p><p>怎样更环保？动物应否成为宠物？喜欢阅读还是看电影及原因？看视频是否有益，想不想成为YouTuber及原因，使用手机是否自律并举例；网上学习模式有什么变化，老师据回答追问。</p><p><strong>尚未实现的愿望</strong></p><p>想做但尚未做到什么？一名考生谈希望设计建筑，现阶段通过游戏和乐高练习，并阅读建筑及抗震设计书籍。</p></blockquote>',19)])])}const i=r(p,[["render",a]]);export{h as __pageData,i as default};
